import org.junit.jupiter.api.Test;

class RestrictionOperatorLawTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final Value ZERO = VF.createLiteral(0);
	private static final Value ONE = VF.createLiteral(1);
	private static final Value TWO = VF.createLiteral(2);
	private static final Value SUBJECT = VF.createIRI("urn:test:s");

	private final QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);

	@Test
	void conflictingProjectionAliasesKeepOnlyTheOriginallyUnboundOccurrence() {
		var child = assignment("x");
		var projection = new Projection(child, new ProjectionElemList(
				new ProjectionElem("x", "a"), new ProjectionElem("x", "b")));
		List<RestrictionFrame> received = new ArrayList<>();
		var childStep = source(child, List.of(row(Map.of()), row(Map.of("x", ZERO)), row(Map.of("x", ONE))), received);
		var plan = RestrictionCompiler.unary("projection/exported-slots", projection, context, childStep,
				RestrictionCompiler.projectionSources(projection)::get,
				(input, cursor) -> new ProjectionIterator(projection, cursor, input, context));
		assertThat(rows(plan, Map.of("a", ZERO, "b", ONE))).containsExactly(row(Map.of()));
		assertThat(received).singleElement()
				.satisfies(frame -> assertThat(frame.unboundOnly(frame.layout().slot("x"))).isTrue());
	}

	@Test
	void optionalMustPreserveWitnessesExcludedByTheCombinedExternalFrame() {
		var left = assignment("s");
		var right = assignment("s", "x", "y");
		var optional = new LeftJoin(left, right);
		List<RestrictionFrame> rightFrames = new ArrayList<>();
		var plan = compile(optional, RestrictionBindJoinIteration.Mode.OPTIONAL,
				List.of(row(Map.of("s", SUBJECT))),
				List.of(row(Map.of("s", SUBJECT, "x", ZERO, "y", ONE)),
						row(Map.of("s", SUBJECT, "x", ONE, "y", ZERO))),
				rightFrames, null);
		assertThat(plan.seekNames()).containsExactly("s");
		assertThat(plan.blueprint().childSlotTransfers().get(1)).allMatch(slot -> slot == -1);
		assertThat(rows(plan, Map.of("x", ZERO, "y", ZERO))).isEmpty();
		assertThat(rightFrames).singleElement().satisfies(frame -> {
			assertThat(frame.value(frame.layout().slot("s"))).isEqualTo(SUBJECT);
			assertThat(frame.value(frame.layout().slot("x"))).isNull();
			assertThat(frame.value(frame.layout().slot("y"))).isNull();
		});
	}

	@Test
	void optionalEstablishesProductiveMatchBeforeApplyingTheOutputResidual() {
		var left = assignment("s");
		var right = assignment("s", "x");
		var optional = new LeftJoin(left, right);
		BindingSet originalLeft = row(Map.of("s", SUBJECT));
		List<BindingSet> originalRight = List.of(row(Map.of("s", SUBJECT, "x", ONE)),
				row(Map.of("s", SUBJECT, "x", TWO)), row(Map.of("s", SUBJECT)));
		QueryValueEvaluationStep condition = row -> {
			Value x = row.getValue("x");
			if (x == null) {
				throw new ValueExprEvaluationException("UNDEF");
			}
			return VF.createLiteral(x.equals(ONE));
		};
		var plan = compile(optional, RestrictionBindJoinIteration.Mode.OPTIONAL, List.of(originalLeft),
				originalRight, new ArrayList<>(), condition);
		assertThat(rows(plan, Map.of("x", ZERO))).isEmpty();
		assertThat(rows(plan, Map.of("x", ONE))).containsExactly(originalRight.getFirst());

		var noWitness = compile(optional, RestrictionBindJoinIteration.Mode.OPTIONAL, List.of(originalLeft),
				originalRight.subList(1, 3), new ArrayList<>(), condition);
		assertThat(rows(noWitness, Map.of("x", ZERO))).containsExactly(originalLeft);
	}

	@Test
	void minusUsesOnlyOriginalComparisonDomainForItsProbeAndWitness() {
		var left = assignment("s");
		var right = assignment("s", "x");
		var minus = new Difference(left, right);
		BindingSet leftWithAmbient = row(Map.of("s", SUBJECT, "x", ZERO));
		List<RestrictionFrame> rightFrames = new ArrayList<>();
		var plan = compile(minus, RestrictionBindJoinIteration.Mode.MINUS, List.of(leftWithAmbient, row(Map.of())),
				List.of(row(Map.of("s", SUBJECT, "x", ONE)), row(Map.of())), rightFrames, null);
		assertThat(rows(plan, Map.of())).containsExactly(row(Map.of()));
		assertThat(rightFrames).hasSize(2);
		assertThat(rightFrames.getFirst().value(rightFrames.getFirst().layout().slot("s"))).isEqualTo(SUBJECT);
		assertThat(rightFrames.getFirst().value(rightFrames.getFirst().layout().slot("x"))).isNull();
		assertThat(rightFrames.getLast().isUnrestricted()).isTrue();
	}

	private PreparedRestrictionPlan compile(BinaryTupleOperator node, RestrictionBindJoinIteration.Mode mode,
			List<BindingSet> leftRows, List<BindingSet> rightRows, List<RestrictionFrame> rightFrames,
			QueryValueEvaluationStep condition) {
		var left = (BindingSetAssignment) node.getLeftArg();
		var right = (BindingSetAssignment) node.getRightArg();
		return RestrictionCompiler.join(node, context, source(left, leftRows, new ArrayList<>()),
				source(right, rightRows, rightFrames), DefaultCollectionFactory::new, Function.identity(),
				mode, condition, left, right);
	}

	private QueryEvaluationStep source(BindingSetAssignment node, List<BindingSet> rows,
			List<RestrictionFrame> received) {
		QueryEvaluationStep source = input -> new CloseableIteratorIteration<>(rows.iterator());
		var layout = new RestrictionLayout(node.getBindingNames(), context);
		var plan = new PreparedRestrictionPlan(
				new RestrictionBlueprint("test/source", RestrictionBlueprint.Realization.STABLE), layout, context,
				node.getBindingNames(), (input, owner) -> PreparedRestrictionPlan.iteratorInvocation(frame -> {
					received.add(frame);
					return RestrictionCompiler.residual(source.evaluate(input), frame);
				}));
		return RestrictionCompiler.attach(source, plan);
	}

	private List<BindingSet> rows(PreparedRestrictionPlan plan, Map<String, Value> requested) {
		var frame = plan.layout().capture(row(requested), Function.identity());
		try (var invocation = plan.open(EmptyBindingSet.getInstance(), InvocationOwner.forExecution(context));
				var rows = invocation.probe(frame)) {
			return QueryResults.asList(rows);
		}
	}

	private static BindingSetAssignment assignment(String... names) {
		var assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(names));
		assignment.setBindingSets(List.of());
		return assignment;
	}

	private static BindingSet row(Map<String, Value> bindings) {
		var row = new MapBindingSet(bindings.size());
		bindings.forEach(row::addBinding);
		return row;
	}
}
